CREATE TYPE public.app_role AS ENUM ('user','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY, name text NOT NULL DEFAULT '', username text UNIQUE, email text, phone text, balance numeric(12,2) NOT NULL DEFAULT 0 CHECK(balance>=0), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,role public.app_role NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role); $$;
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin'); $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.is_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_admin() TO anon,authenticated,service_role;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_admin());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid() OR public.is_admin()) WITH CHECK(id=auth.uid() OR public.is_admin());
CREATE POLICY profiles_delete ON public.profiles FOR DELETE TO authenticated USING(public.is_admin());
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin());
CREATE FUNCTION public.ensure_profile() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u record; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; SELECT id,email,raw_user_meta_data INTO u FROM auth.users WHERE id=auth.uid(); INSERT INTO public.profiles(id,name,username,email,phone) VALUES(u.id,coalesce(u.raw_user_meta_data->>'name',''),nullif(lower(coalesce(u.raw_user_meta_data->>'username','')),''),u.email,nullif(u.raw_user_meta_data->>'phone','')) ON CONFLICT(id) DO NOTHING; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'user') ON CONFLICT DO NOTHING; END; $$;
REVOKE ALL ON FUNCTION public.ensure_profile() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.ensure_profile() TO authenticated;
CREATE FUNCTION public.protect_profile_fields() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF current_user='postgres' OR auth.uid() IS NULL OR public.is_admin() OR current_setting('app.bypass_profile_guard',true)='on' THEN RETURN NEW; END IF; NEW.balance:=OLD.balance; NEW.is_active:=OLD.is_active; NEW.id:=OLD.id; NEW.email:=OLD.email; RETURN NEW; END; $$;
CREATE TRIGGER protect_profile BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_profile_fields();
CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TABLE public.categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text NOT NULL UNIQUE,image_url text,sort_order integer NOT NULL DEFAULT 0,is_active boolean NOT NULL DEFAULT true,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.categories TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY categories_read ON public.categories FOR SELECT TO anon,authenticated USING(is_active OR public.is_admin()); CREATE POLICY categories_admin ON public.categories FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text NOT NULL UNIQUE,category_id uuid REFERENCES public.categories(id) ON DELETE SET NULL,short_description text DEFAULT '',full_description text DEFAULT '',features text[] NOT NULL DEFAULT '{}',image_url text,images text[] NOT NULL DEFAULT '{}',price numeric(12,2) NOT NULL DEFAULT 0 CHECK(price>=0),discount_price numeric(12,2) CHECK(discount_price>=0),stock integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'in_stock',demo_url text,purchase_url text,is_featured boolean NOT NULL DEFAULT false,is_best_seller boolean NOT NULL DEFAULT false,is_active boolean NOT NULL DEFAULT true,sort_order integer NOT NULL DEFAULT 0,is_demo boolean NOT NULL DEFAULT false,is_verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY products_read ON public.products FOR SELECT TO anon,authenticated USING(is_active OR public.is_admin()); CREATE POLICY products_admin ON public.products FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.product_packages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,name text NOT NULL,duration text NOT NULL DEFAULT '',price numeric(12,2) NOT NULL DEFAULT 0 CHECK(price>=0),is_active boolean NOT NULL DEFAULT true,sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.product_packages TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.product_packages TO authenticated; GRANT ALL ON public.product_packages TO service_role;
ALTER TABLE public.product_packages ENABLE ROW LEVEL SECURITY;
CREATE POLICY packages_read ON public.product_packages FOR SELECT TO anon,authenticated USING((is_active AND EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND p.is_active)) OR public.is_admin()); CREATE POLICY packages_admin ON public.product_packages FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,product_id uuid REFERENCES public.products(id) ON DELETE SET NULL,product_name text NOT NULL,quantity integer NOT NULL DEFAULT 1,unit_price numeric(12,2) NOT NULL DEFAULT 0,total numeric(12,2) NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'pending',note text,delivered_key text,package_id uuid REFERENCES public.product_packages(id) ON DELETE SET NULL,package_name text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,DELETE ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY orders_read ON public.orders FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin()); CREATE POLICY orders_update ON public.orders FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin()); CREATE POLICY orders_delete ON public.orders FOR DELETE TO authenticated USING(public.is_admin());
CREATE TABLE public.product_keys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,package_id uuid REFERENCES public.product_packages(id) ON DELETE CASCADE,key_value text NOT NULL,is_used boolean NOT NULL DEFAULT false,used_by uuid,order_id uuid REFERENCES public.orders(id) ON DELETE SET NULL,used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(product_id,key_value));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.product_keys TO authenticated; GRANT ALL ON public.product_keys TO service_role;
ALTER TABLE public.product_keys ENABLE ROW LEVEL SECURITY;
CREATE POLICY keys_admin ON public.product_keys FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.wallet_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,amount numeric(12,2) NOT NULL,type text NOT NULL,description text,balance_after numeric(12,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.wallet_transactions TO authenticated; GRANT ALL ON public.wallet_transactions TO service_role;
ALTER TABLE public.wallet_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY wallet_read ON public.wallet_transactions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin());
CREATE TABLE public.accepted_trx(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trx_id text NOT NULL,method text NOT NULL CHECK(method IN('bkash','nagad')),amount numeric(12,2) NOT NULL CHECK(amount>0),status text NOT NULL DEFAULT 'available' CHECK(status IN('available','used','disabled')),notes text,used_by uuid,used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.accepted_trx TO authenticated; GRANT ALL ON public.accepted_trx TO service_role;
ALTER TABLE public.accepted_trx ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX accepted_trx_unique ON public.accepted_trx(upper(trim(trx_id)));
CREATE POLICY trx_admin ON public.accepted_trx FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,amount numeric(12,2) NOT NULL,method text NOT NULL,trx_id text NOT NULL,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,DELETE ON public.payments TO authenticated; GRANT ALL ON public.payments TO service_role;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY payments_read ON public.payments FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin()); CREATE POLICY payments_update ON public.payments FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin()); CREATE POLICY payments_delete ON public.payments FOR DELETE TO authenticated USING(public.is_admin());
CREATE TABLE public.announcements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,message text NOT NULL DEFAULT '',type text NOT NULL DEFAULT 'banner',start_date timestamptz,end_date timestamptz,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.announcements TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.announcements TO authenticated; GRANT ALL ON public.announcements TO service_role;
ALTER TABLE public.announcements ENABLE ROW LEVEL SECURITY;
CREATE POLICY announcements_read ON public.announcements FOR SELECT TO anon,authenticated USING(is_active OR public.is_admin()); CREATE POLICY announcements_admin ON public.announcements FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.site_settings(key text PRIMARY KEY,value text NOT NULL DEFAULT '',updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_settings TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.site_settings TO authenticated; GRANT ALL ON public.site_settings TO service_role;
ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_read ON public.site_settings FOR SELECT TO anon,authenticated USING(true); CREATE POLICY settings_admin ON public.site_settings FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.homepage_sections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),key text NOT NULL UNIQUE,title text NOT NULL DEFAULT '',subtitle text DEFAULT '',is_enabled boolean NOT NULL DEFAULT true,sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.homepage_sections TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.homepage_sections TO authenticated; GRANT ALL ON public.homepage_sections TO service_role;
ALTER TABLE public.homepage_sections ENABLE ROW LEVEL SECURITY;
CREATE POLICY sections_read ON public.homepage_sections FOR SELECT TO anon,authenticated USING(true); CREATE POLICY sections_admin ON public.homepage_sections FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.uddoktapay_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,invoice_id text NOT NULL UNIQUE,amount numeric NOT NULL CHECK(amount>0),status text NOT NULL DEFAULT 'pending',payment_method text,sender_number text,transaction_id text,raw jsonb,credited_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.uddoktapay_payments TO authenticated; GRANT ALL ON public.uddoktapay_payments TO service_role;
ALTER TABLE public.uddoktapay_payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY auto_payments_read ON public.uddoktapay_payments FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin());
CREATE TABLE public.telegram_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE,telegram_user_id bigint NOT NULL UNIQUE,telegram_chat_id bigint NOT NULL,telegram_username text,linked_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.telegram_links TO authenticated; GRANT ALL ON public.telegram_links TO service_role;
ALTER TABLE public.telegram_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY telegram_read ON public.telegram_links FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin());
CREATE TABLE public.telegram_sessions(chat_id bigint PRIMARY KEY,state text NOT NULL DEFAULT '',data jsonb NOT NULL DEFAULT '{}'::jsonb,updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.telegram_sessions TO service_role;
ALTER TABLE public.telegram_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),subject text NOT NULL,message text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','resolved')),source text NOT NULL DEFAULT 'customer',amount numeric,trx_ids text[] NOT NULL DEFAULT '{}',attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.support_tickets TO authenticated; GRANT ALL ON public.support_tickets TO service_role;
ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY;
CREATE POLICY ticket_read ON public.support_tickets FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin()); CREATE POLICY ticket_create ON public.support_tickets FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND source='customer' AND status='open' AND attempts=0 AND cardinality(trx_ids)=0); CREATE POLICY ticket_admin ON public.support_tickets FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.support_replies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid NOT NULL REFERENCES public.support_tickets(id),user_id uuid NOT NULL REFERENCES public.profiles(id),message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.support_replies TO authenticated; GRANT ALL ON public.support_replies TO service_role;
ALTER TABLE public.support_replies ENABLE ROW LEVEL SECURITY;
CREATE POLICY reply_read ON public.support_replies FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.support_tickets t WHERE t.id=ticket_id AND(t.user_id=auth.uid() OR public.is_admin()))); CREATE POLICY reply_create ON public.support_replies FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.support_tickets t WHERE t.id=ticket_id AND t.status='open' AND(t.user_id=auth.uid() OR public.is_admin())));
CREATE TABLE public.admin_event_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_key text NOT NULL UNIQUE,kind text NOT NULL,user_id uuid,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.admin_event_outbox TO service_role;
ALTER TABLE public.admin_event_outbox ENABLE ROW LEVEL SECURITY;
CREATE TRIGGER products_updated BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER orders_updated BEFORE UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER packages_updated BEFORE UPDATE ON public.product_packages FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();